:root {
  --color-primary: #1a5f7a;
  --color-primary-dark: #0d3d52;
  --color-accent: #e8f4f8;
  --color-accent-on-dark: #a8d8e8;
  --color-text: #1a1a1a;
  --color-text-light: #666666;
  --color-bg: #ffffff;
  --color-border: #e0e0e0;
  --color-success: #2d7a5a;
  --spacing-xs: 0.5rem;
  --spacing-sm: 1rem;
  --spacing-md: 1.5rem;
  --spacing-lg: 2rem;
  --spacing-xl: 3rem;
  --font-primary: Georgia, "Times New Roman", serif;
  --font-sans: "Trebuchet MS", Verdana, sans-serif;
  --font-mono: "Courier New", monospace;
  --shadow-sm: 0 2px 4px rgba(26, 95, 122, 0.1);
  --shadow-md: 0 4px 8px rgba(26, 95, 122, 0.15);
  --shadow-lg: 0 8px 16px rgba(26, 95, 122, 0.2);
}

* {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  margin: 0;
  padding: 0;
  font-family: var(--font-sans);
  font-size: 1rem;
  line-height: 1.6;
  color: var(--color-text);
  background-color: var(--color-bg);
}

h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-primary);
  margin-top: var(--spacing-lg);
  margin-bottom: var(--spacing-sm);
  line-height: 1.3;
  color: var(--color-primary-dark);
}

h1 {
  font-size: 2.5rem;
}

h2 {
  font-size: 2rem;
}

h3 {
  font-size: 1.5rem;
}

p {
  margin-top: 0;
  margin-bottom: var(--spacing-md);
}

a {
  color: var(--color-primary-dark);
  text-decoration: none;
  transition: color 0.2s ease;
}

a:hover {
  color: var(--color-primary);
}

a:focus {
  outline: 3px solid var(--color-primary);
  outline-offset: 2px;
  border-radius: 2px;
}

.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 var(--spacing-md);
}

/* Header */
header {
  background-color: var(--color-bg);
  border-bottom: 2px solid var(--color-border);
  position: sticky;
  top: 0;
  z-index: 100;
  box-shadow: var(--shadow-sm);
}

.header-content {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: var(--spacing-md) 0;
  flex-wrap: wrap;
}

.logo {
  font-family: "Palatino Linotype", "Book Antiqua", serif;
  font-size: clamp(1.3rem, 5vw, 1.8rem);
  font-weight: 700;
  font-variant: small-caps;
  letter-spacing: 0.15em;
  color: var(--color-primary-dark);
  border-bottom: 2px solid var(--color-primary-dark);
  padding-bottom: 0.3rem;
  white-space: nowrap;
}

.logo:hover,
.logo:focus {
  color: var(--color-primary);
  border-bottom-color: var(--color-primary);
}

header nav {
  display: flex;
  gap: var(--spacing-md);
  flex-wrap: wrap;
  align-items: center;
}

header nav a {
  padding: var(--spacing-xs) var(--spacing-sm);
  font-weight: 600;
  border-radius: 4px;
  transition: background-color 0.2s ease;
}

header nav a:hover {
  background-color: var(--color-accent);
}

header nav a:focus {
  outline: 3px solid var(--color-primary);
  outline-offset: 2px;
}

/* Footer */
footer {
  background-color: var(--color-primary-dark);
  color: var(--color-accent-on-dark);
  padding: var(--spacing-xl) 0 var(--spacing-lg);
  margin-top: var(--spacing-xl);
}

footer h3 {
  color: var(--color-accent-on-dark);
  margin-top: 0;
}

footer a {
  color: var(--color-accent-on-dark);
}

footer a:hover {
  text-decoration: underline;
}

.footer-content {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: var(--spacing-lg);
  margin-bottom: var(--spacing-lg);
}

.footer-section p {
  margin-bottom: var(--spacing-sm);
}

.footer-bottom {
  border-top: 1px solid rgba(255, 255, 255, 0.2);
  padding-top: var(--spacing-md);
  text-align: center;
  font-size: 0.9rem;
}

/* Buttons */
button,
.button {
  display: inline-block;
  padding: var(--spacing-sm) var(--spacing-lg);
  min-height: 44px;
  background-color: var(--color-primary-dark);
  color: #ffffff;
  border: none;
  border-radius: 6px;
  font-size: 1rem;
  font-family: var(--font-sans);
  font-weight: 600;
  cursor: pointer;
  text-decoration: none;
  transition: background-color 0.2s ease, transform 0.1s ease;
  text-align: center;
  display: flex;
  align-items: center;
  justify-content: center;
}

button:hover,
.button:hover {
  background-color: var(--color-primary);
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}

button:focus,
.button:focus {
  outline: 3px solid var(--color-primary);
  outline-offset: 2px;
}

button:active {
  transform: translateY(0);
}

/* Forms */
form {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-md);
}

label {
  display: block;
  margin-bottom: var(--spacing-xs);
  font-weight: 600;
  color: var(--color-primary-dark);
}

input,
textarea,
select {
  min-height: 44px;
  padding: var(--spacing-sm);
  border: 2px solid var(--color-border);
  border-radius: 6px;
  font-family: var(--font-sans);
  font-size: 1rem;
  color: var(--color-text);
  background-color: var(--color-bg);
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
}

input:focus,
textarea:focus,
select:focus {
  outline: none;
  border-color: var(--color-primary-dark);
  box-shadow: 0 0 0 3px rgba(26, 95, 122, 0.1);
}

textarea {
  min-height: 120px;
  resize: vertical;
  font-family: var(--font-sans);
}

/* Cards */
.card {
  background-color: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: 8px;
  padding: var(--spacing-lg);
  box-shadow: var(--shadow-sm);
  transition: box-shadow 0.2s ease, transform 0.2s ease;
}

.card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-4px);
}

/* Grid */
.grid {
  display: grid;
  gap: var(--spacing-lg);
}

.grid-2 {
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
}

.grid-3 {
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
}

/* Mobile */
@media (max-width: 600px) {
  h1 {
    font-size: 1.8rem;
  }

  h2 {
    font-size: 1.5rem;
  }

  h3 {
    font-size: 1.2rem;
  }

  .container {
    padding: 0 var(--spacing-sm);
  }

  .header-content {
    flex-direction: column;
    gap: var(--spacing-sm);
    padding: var(--spacing-sm) 0;
  }

  header nav {
    flex-direction: column;
    width: 100%;
    gap: var(--spacing-xs);
  }

  header nav a {
    width: 100%;
    text-align: center;
    padding: var(--spacing-sm);
  }

  .grid-2,
  .grid-3 {
    grid-template-columns: 1fr;
  }

  .footer-content {
    grid-template-columns: 1fr;
    gap: var(--spacing-md);
  }
}

/* Desktop */
@media (min-width: 601px) {
  .container {
    padding: 0 var(--spacing-lg);
  }

  header nav {
    gap: var(--spacing-lg);
  }

  .grid-2 {
    grid-template-columns: repeat(2, 1fr);
  }

  .grid-3 {
    grid-template-columns: repeat(3, 1fr);
  }
}

/* Utilities */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border-width: 0;
}

.text-center {
  text-align: center;
}

.text-muted {
  color: var(--color-text-light);
}

.mb-0 {
  margin-bottom: 0;
}

.mt-lg {
  margin-top: var(--spacing-lg);
}

/* Accessibility */
@media (prefers-reduced-motion: reduce) {
  * {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

