.index-hero {
  background-color: var(--color-accent);
  padding: var(--spacing-xl) 0;
  text-align: center;
}

.index-hero h1 {
  margin-top: 0;
  color: var(--color-primary-dark);
  font-size: clamp(2rem, 8vw, 3rem);
}

.index-hero-subtitle {
  font-size: 1.1rem;
  color: var(--color-text);
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
  margin-bottom: var(--spacing-lg);
}

.index-cta-button {
  font-size: 1.1rem;
  padding: var(--spacing-md) var(--spacing-xl);
}

.index-services {
  padding: var(--spacing-xl) 0;
  background-color: var(--color-bg);
}

.index-services h2 {
  text-align: center;
}

.index-services-intro {
  text-align: center;
  font-size: 1.1rem;
  color: var(--color-text-light);
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
  margin-bottom: var(--spacing-lg);
}

.index-service-card h3 {
  margin-top: 0;
}

.index-service-card a {
  font-weight: 600;
  color: var(--color-primary-dark);
  display: inline-block;
  padding-bottom: 0.25rem;
  border-bottom: 2px solid var(--color-primary-dark);
  transition: all 0.2s ease;
}

.index-service-card a:hover {
  color: var(--color-primary);
  border-bottom-color: var(--color-primary);
}

.index-services-cta {
  margin-top: var(--spacing-xl);
}

.index-testimonials {
  padding: var(--spacing-xl) 0;
  background-color: var(--color-accent);
}

.index-testimonials h2 {
  text-align: center;
}

.index-testimonials-intro {
  text-align: center;
  font-size: 1.1rem;
  color: var(--color-text-light);
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
  margin-bottom: var(--spacing-lg);
}

.index-testimonial-card {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}

.index-testimonial-text {
  font-style: italic;
  color: var(--color-text);
  margin-bottom: var(--spacing-md);
  flex-grow: 1;
}

.index-testimonial-author {
  font-weight: 600;
  color: var(--color-primary-dark);
  margin-bottom: 0;
}

.index-about {
  padding: var(--spacing-xl) 0;
  background-color: var(--color-bg);
}

.index-about h2 {
  text-align: center;
  margin-bottom: var(--spacing-lg);
}

.index-about-item h3 {
  color: var(--color-primary-dark);
  margin-top: 0;
}

.index-contact-cta {
  padding: var(--spacing-xl) 0;
  background-color: var(--color-primary-dark);
  color: var(--color-accent-on-dark);
  text-align: center;
}

.index-contact-cta h2 {
  color: var(--color-accent-on-dark);
}

.index-contact-cta p {
  color: var(--color-accent-on-dark);
  font-size: 1.1rem;
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
}

.index-contact-buttons {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-md);
  align-items: center;
  margin-top: var(--spacing-lg);
}

.index-call-button {
  background-color: var(--color-success);
}

.index-call-button:hover {
  background-color: #1f5f41;
}

@media (max-width: 600px) {
  .index-hero {
    padding: var(--spacing-lg) 0;
  }

  .index-hero h1 {
    font-size: 1.8rem;
  }

  .index-hero-subtitle {
    font-size: 1rem;
  }

  .index-services {
    padding: var(--spacing-lg) 0;
  }

  .index-testimonials {
    padding: var(--spacing-lg) 0;
  }

  .index-about {
    padding: var(--spacing-lg) 0;
  }

  .index-contact-cta {
    padding: var(--spacing-lg) 0;
  }

  .index-contact-buttons {
    flex-direction: column;
  }

  .index-contact-buttons .button {
    width: 100%;
