  .index-hero {
    padding: var(--spacing-xl) 0;
  }

  .index-contact-buttons {
    flex-direction: row;
    justify-content: center;
  }
}

.services-intro {
  background-color: var(--color-accent);
  padding: var(--spacing-lg) 0;
  margin-bottom: var(--spacing-xl);
}

.services-intro p {
  font-size: 1.1rem;
  color: var(--color-primary-dark);
  max-width: 800px;
}

.services-category {
  margin-bottom: var(--spacing-xl);
}

.services-category h2 {
  margin-top: 0;
  padding-bottom: var(--spacing-md);
  border-bottom: 3px solid var(--color-primary-dark);
}

.service-card h3 {
  margin-top: 0;
  color: var(--color-primary-dark);
  font-size: 1.3rem;
}

.service-description {
  color: var(--color-text-light);
  margin-bottom: var(--spacing-md);
  min-height: 3em;
}

.service-meta {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-xs);
  padding-top: var(--spacing-md);
  border-top: 1px solid var(--color-border);
  font-weight: 600;
}

.service-duration {
  color: var(--color-text-light);
  font-size: 0.95rem;
}

.service-price {
  color: var(--color-primary-dark);
  font-size: 1.3rem;
}

.services-info {
  margin-bottom: var(--spacing-xl);
}

.info-box {
  background-color: var(--color-accent);
  border-left: 4px solid var(--color-primary-dark);
  padding: var(--spacing-lg);
  margin-bottom: var(--spacing-md);
  border-radius: 4px;
}

.info-box h3 {
  margin-top: 0;
  color: var(--color-primary-dark);
}

.info-box p {
  margin-bottom: 0;
  color: var(--color-text);
}

.services-cta {
  background-color: var(--color-primary-dark);
  color: #ffffff;
  padding: var(--spacing-xl) 0;
  text-align: center;
  border-radius: 8px;
  margin-bottom: var(--spacing-xl);
}

.services-cta h2 {
  color: #ffffff;
  margin-top: 0;
}

.services-cta p {
  color: var(--color-accent-on-dark);
  font-size: 1.1rem;
  margin-bottom: var(--spacing-lg);
}

.services-cta .button {
  background-color: #ffffff;
  color: var(--color-primary-dark);
  font-weight: 700;
  padding: var(--spacing-sm) var(--spacing-lg);
}

.services-cta .button:hover {
  background-color: var(--color-accent);
}

@media (max-width: 600px) {
  .services-intro {
    margin-bottom: var(--spacing-lg);
  }

  .services-category {
    margin-bottom: var(--spacing-lg);
  }

  .services-category h2 {
    font-size: 1.5rem;
    padding-bottom: var(--spacing-sm);
  }

  .service-meta {
    flex-direction: row;
    justify-content: space-between;
    align-items: center;
  }

  .services-cta {
    margin-bottom: var(--spacing-lg);
    padding: var(--spacing-lg) 0;
  }
}

@media (min-width: 601px) {
  .service-meta {
    display: flex;
    flex-direction: row;
    justify-content: space-between;
    align-items: flex-end;
  }

  .service-duration {
    flex: 1;
  }

  .service-price {
    text-align: right;
  }
}

.team-intro {
  background: linear-gradient(135deg, var(--color-primary) 0%, var(--color-primary-dark) 100%);
  color: white;
  padding: var(--spacing-xl) 0;
}

.team-intro h1 {
  color: white;
  margin-top: 0;
}

.team-intro p {
  color: var(--color-accent-on-dark);
  font-size: 1.1rem;
}

.team-doctors,
.team-support {
  padding: var(--spacing-xl) 0;
}

.team-doctors h2,
.team-support h2,
.team-values h2 {
  text-align: center;
  margin-bottom: var(--spacing-xl);
}

.team-grid {
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: var(--spacing-lg);
}

.team-card {
  background-color: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: 8px;
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: box-shadow 0.3s ease, transform 0.3s ease;
  display: flex;
  flex-direction: column;
}

.team-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-6px);
}

.team-card img {
  width: 100%;
  height: 300px;
  object-fit: cover;
  display: block;
}

.team-card-content {
  padding: var(--spacing-lg);
  flex-grow: 1;
  display: flex;
  flex-direction: column;
}

.team-card h3 {
  margin-top: 0;
  margin-bottom: var(--spacing-xs);
  font-size: 1.3rem;
}

.team-specialty {
  color: var(--color-primary-dark);
  font-weight: 600;
  margin-bottom: var(--spacing-md);
  font-size: 0.95rem;
}

.team-card p:last-child {
  margin-bottom: 0;
  flex-grow: 1;
  color: var(--color-text-light);
  font-size: 0.95rem;
}

.team-values {
  background-color: var(--color-accent);
  padding: var(--spacing-xl) 0;
}

.team-values-grid {
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: var(--spacing-lg);
}

.team-value-card {
  background-color: white;
  padding: var(--spacing-lg);
  border-radius: 8px;
  border-left: 4px solid var(--color-primary-dark);
  box-shadow: var(--shadow-sm);
  transition: transform 0.3s ease, box-shadow 0.3s ease;
}

.team-value-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-md);
}

.team-value-card h3 {
  margin-top: 0;
  color: var(--color-primary-dark);
  font-size: 1.2rem;
}

.team-value-card p {
  margin-bottom: 0;
  color: var(--color-text-light);
  font-size: 0.95rem;
}

@media (max-width: 600px) {
  .team-intro {
    padding: var(--spacing-lg) 0;
  }

  .team-intro h1 {
    font-size: 1.8rem;
  }

  .team-intro p {
    font-size: 1rem;
  }

  .team-doctors,
  .team-support,
  .team-values {
    padding: var(--spacing-lg) 0;
  }

  .team-grid {
    grid-template-columns: 1fr;
  }

  .team-values-grid {
    grid-template-columns: 1fr;
  }

  .team-card img {
    height: 250px;
  }
}

@media (min-width: 601px) {
  .team-grid {
    grid-template-columns: repeat(3, 1fr);
  }

  .team-values-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (min-width: 900px) {
  .team-values-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

.appointment-intro {
  padding: var(--spacing-lg) 0;
  background-color: var(--color-accent);
}

.appointment-intro p {
  font-size: 1.1rem;
  text-align: center;
  margin-bottom: 0;
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
}

.appointment-content {
  padding: var(--spacing-lg) 0;
}

.appointment-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--spacing-xl);
  align-items: start;
}

.appointment-form-wrapper h2 {
  margin-top: 0;
  color: var(--color-primary-dark);
}

.appointment-form {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-md);
}

.appointment-form label {
  display: block;
  margin-bottom: var(--spacing-xs);
  font-weight: 600;
  color: var(--color-primary-dark);
}

.appointment-form input,
.appointment-form select,
.appointment-form textarea {
  width: 100%;
  min-height: 44px;
  padding: var(--spacing-sm);
  border: 2px solid var(--color-border);
  border-radius: 6px;
  font-family: var(--font-sans);
  font-size: 1rem;
  color: var(--color-text);
  background-color: var(--color-bg);
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
}

.appointment-form input:focus,
.appointment-form select:focus,
.appointment-form textarea:focus {
  outline: none;
  border-color: var(--color-primary-dark);
  box-shadow: 0 0 0 3px rgba(26, 95, 122, 0.1);
}

.appointment-form textarea {
  min-height: 120px;
  resize: vertical;
}

.appointment-submit {
  min-height: 44px;
  padding: var(--spacing-sm) var(--spacing-lg);
  background-color: var(--color-primary-dark);
  color: #ffffff;
  border: none;
  border-radius: 6px;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: background-color 0.2s ease, transform 0.1s ease, box-shadow 0.2s ease;
  text-align: center;
}

.appointment-submit:hover {
  background-color: var(--color-primary);
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}

.appointment-submit:focus {
  outline: 3px solid var(--color-primary);
  outline-offset: 2px;
}

.appointment-submit:active {
  transform: translateY(0);
}

.appointment-info h2 {
  margin-top: 0;
  color: var(--color-primary-dark);
}

.appointment-card {
  background-color: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: 8px;
