}

.appointment-form-wrapper h2 {
  margin-top: 0;
  color: var(--color-primary-dark);
}

.appointment-form {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-md);
}

.appointment-form label {
  display: block;
  margin-bottom: var(--spacing-xs);
  font-weight: 600;
  color: var(--color-primary-dark);
}

.appointment-form input,
.appointment-form select,
.appointment-form textarea {
  width: 100%;
  min-height: 44px;
  padding: var(--spacing-sm);
  border: 2px solid var(--color-border);
  border-radius: 6px;
  font-family: var(--font-sans);
  font-size: 1rem;
  color: var(--color-text);
  background-color: var(--color-bg);
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
}

.appointment-form input:focus,
.appointment-form select:focus,
.appointment-form textarea:focus {
  outline: none;
  border-color: var(--color-primary-dark);
  box-shadow: 0 0 0 3px rgba(26, 95, 122, 0.1);
}

.appointment-form textarea {
  min-height: 120px;
  resize: vertical;
}

.appointment-submit {
  min-height: 44px;
  padding: var(--spacing-sm) var(--spacing-lg);
  background-color: var(--color-primary-dark);
  color: #ffffff;
  border: none;
  border-radius: 6px;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: background-color 0.2s ease, transform 0.1s ease, box-shadow 0.2s ease;
  text-align: center;
}

.appointment-submit:hover {
  background-color: var(--color-primary);
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}

.appointment-submit:focus {
  outline: 3px solid var(--color-primary);
  outline-offset: 2px;
}

.appointment-submit:active {
  transform: translateY(0);
}

.appointment-info h2 {
  margin-top: 0;
  color: var(--color-primary-dark);
}

.appointment-card {
  background-color: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: 8px;
  padding: var(--spacing-lg);
  margin-bottom: var(--spacing-lg);
  box-shadow: var(--shadow-sm);
  transition: box-shadow 0.2s ease, transform 0.2s ease;
}

.appointment-card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}

.appointment-card h3 {
  margin-top: 0;
  margin-bottom: var(--spacing-sm);
  color: var(--color-primary-dark);
}

.appointment-card p {
  margin-bottom: var(--spacing-sm);
}

.appointment-card p:last-child {
  margin-bottom: 0;
}

.appointment-card a {
  color: var(--color-primary-dark);
  font-weight: 600;
  text-decoration: underline;
}

.appointment-card a:hover {
  color: var(--color-primary);
}

.appointment-hours {
  list-style: none;
  padding: 0;
  margin: 0;
}

.appointment-hours li {
  padding: var(--spacing-xs) 0;
  border-bottom: 1px solid var(--color-border);
  line-height: 1.8;
}

.appointment-hours li:last-child {
  border-bottom: none;
}

.appointment-card-notice {
  background-color: var(--color-accent);
  border-color: var(--color-primary);
}

.appointment-card-notice h3 {
  color: var(--color-primary-dark);
}

/* Mobile */
@media (max-width: 600px) {
  .appointment-intro {
    padding: var(--spacing-md) 0;
  }

  .appointment-content {
    padding: var(--spacing-md) 0;
  }

  .appointment-grid {
    grid-template-columns: 1fr;
    gap: var(--spacing-lg);
  }

  .appointment-form-wrapper h2,
  .appointment-info h2 {
    font-size: 1.5rem;
    margin-top: var(--spacing-md);
  }

  .appointment-form-wrapper h2:first-child,
  .appointment-info h2:first-child {
    margin-top: 0;
  }
}

/* Desktop */
@media (min-width: 601px) {
  .appointment-grid {
    grid-template-columns: 1fr 1fr;
  }
}
